    <section class="surface panel"><div class="section-heading"><div><h2 class="section-title">Informasi kantin</h2><p>Informasi publik dari konfigurasi repository.</p></div><a href="#/transparency" class="text-link">Lihat transparansi ${icon('arrow',15)}</a></div><div class="form-grid"><div><span class="muted small">Jam operasional</span><p style="font-weight:800;margin:5px 0 0">${escapeHtml(s.operatingHours||'Belum diatur')}</p></div><div><span class="muted small">Metode pembayaran</span><p style="font-weight:800;margin:5px 0 0">${s.cashEnabled!==false?'Tunai':''}${s.cashEnabled!==false&&qrisConfigured(s)?' · ':''}${qrisConfigured(s)?'QRIS':''}${s.cashEnabled===false&&!qrisConfigured(s)?'Belum tersedia':''}</p></div></div></section>
